from PIL import Image
im=np.asarray(Image.open('/app/output/current_ego.png')).astype(int);D=np.load('/app/output/current_depth_ego.npy')
# brown mug hue condition
m=(im[:,:,0]>im[:,:,1]*1.20)&(im[:,:,1]>im[:,:,2]*1.18)&(im[:,:,0]>65)&(im[:,:,0]<240)&(im[:,:,1]<220)&(D>0)
roi=np.zeros_like(m);roi[260:345,280:380]=1;m &= roi
ys,xs=np.where(m);print('pixels',len(xs),'bbox',xs.min(),xs.max(),ys.min(),ys.max())
meta=json.load(open('/app/output/current_meta.json'))['cameras']['ego'];K=np.array(meta['intrinsic_cv']);R=np.array(meta['extrinsic_cv'])[:,:3];t=np.array(meta['extrinsic_cv'])[:,3];
u=np.stack([xs,ys,np.ones_like(xs)]);z=D[ys,xs];cam=np.linalg.inv(K)@u*z;world=np.linalg.inv(R)@(cam-t[:,None]);
for i,n in enumerate('xyz'):
 print(n,np.percentile(world[i],[2,10,25,50,75,90,98]))
for row in (270,278,285,290,295,300,305,310,315,320,325,330):
 pts=[(x,tuple(im[row,x]),round(float(D[row,x]),3)) for x in range(285,375) if m[row,x]]
 if pts:print(row,pts[:3],pts[-3:])
