import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=60);o=r.get_obs(video='none');n=np.array(o.meta['proprio']['now']);q=np.r_[n[:7],n[8:15]];p=n[23:30];q0=p[3:7];q1=np.array([0,.5,.8660254,0.]);dot=q0@q1
if dot<0:q1=-q1;dot=-dot
ang=np.arccos(np.clip(dot,-1,1));
def sl(a):return (np.sin((1-a)*ang)*q0+np.sin(a*ang)*q1)/np.sin(ang)
path=[(p[:3],0),(p[:3],.5),(p[:3],1),(np.array([.57,.23,.96]),1),(np.array([.50,.15,.96]),1),(np.array([.50,.15,.90]),1),(np.array([.50,.15,.80]),1)]
for i,(xyz,a) in enumerate(path):
 qq=sl(a); ans=r.ik({'Gripper_Tip_L':[*xyz,*qq]},seed=q,max_iters=200)
 print(i,np.round(xyz,3),a,ans['ok'],ans.get('error'))
 if ans['ok']:
  qn=np.array(ans['q']); print(' qL',np.round(qn[7:],3),'dq',np.round(qn[7:]-q[7:],3));q=qn
 else: print('qL',np.round(ans.get('q',[0]*14)[7:],3))
PY

